```sql
alter table public.teams enable row level security;
alter table public.team_members enable row level security;
alter table public.documents enable row level security;

create function public.is_team_member(target_team_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.team_members
    where team_id = target_team_id
      and user_id = auth.uid()
  );
$$;

create function public.is_team_editor(target_team_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.team_members
    where team_id = target_team_id
      and user_id = auth.uid()
      and role = 'editor'
  );
$$;

create function public.can_read_document(target_document_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.documents
    where id = target_document_id
      and team_id => public.is_team_member(documents.team_id)
      and deleted_at is null
  );
$$;

create function public.can_edit_document(target_document_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.documents
    where id = target_document_id
      and public.is_team_editor(documents.team_id)
  );
$$;

create function public.enforce_team_immutability()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return old;
  end if;

  if tg_op = 'INSERT' then
    raise exception 'teams cannot be inserted by users';
  elsif tg_op = 'UPDATE' then
    if new.id is distinct from old.id
       or new.name is distinct from old.name then
      raise exception 'teams cannot be modified by users';
    end if;
  elsif tg_op = 'DELETE' then
    raise exception 'teams cannot be deleted by users';
  end if;

  return old;
end;
$$;

create function public.enforce_team_membership_immutability()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return old;
  end if;

  if tg_op = 'INSERT' then
    raise exception 'team_members cannot be inserted by users';
  elsif tg_op = 'UPDATE' then
    if new.team_id is distinct from old.team_id
       or new.user_id is distinct from old.user_id
       or new.role is distinct from old.role then
      raise exception 'team_members cannot be modified by users';
    end if;
  elsif tg_op = 'DELETE' then
    raise exception 'team_members cannot be deleted by users';
  end if;

  return old;
end;
$$;

create function public.enforce_document_constraints()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return old;
  end if;

  if tg_op = 'INSERT' then
    if new.created_by is distinct from auth.uid() then
      raise exception 'documents must be created by the current user';
    end if;

    if not public.is_team_member(new.team_id) then
      raise exception 'cannot create documents outside your teams';
    end if;

    if public.is_team_editor(new.team_id) then
      new.role := 'editor';
    else
      new.role := 'viewer';
    end if;
  elsif tg_op = 'UPDATE' then
    if new.team_id is distinct from old.team_id then
      raise exception 'document team cannot be changed';
    end if;

    if public.is_team_editor(old.team_id) then
      if new.created_by is distinct from old.created_by then
        raise exception 'document creator cannot be changed';
      end if;

      if not public.is_team_editor(new.team_id) then
        raise exception 'only editors can edit documents';
      end if;
    else
      raise exception 'only editors can edit documents';
    end if;
  elsif tg_op = 'DELETE' then
    if auth.uid() is distinct from old.created_by then
      raise exception 'only the document creator can delete it';
    end if;
  end if;

  return old;
end;
$$;

create trigger teams_enforce_immutability
before insert or update or delete on public.teams
for each row
execute function public.enforce_team_immutability();

create trigger team_members_enforce_immutability
before insert or update or delete on public.team_members
for each row
execute function public.enforce_team_membership_immutability();

create trigger documents_enforce_constraints
before insert or update or delete on public.documents
for each row
execute function public.enforce_document_constraints();

create policy teams_select_members
on public.teams
for select
to authenticated
using (public.is_team_member(id));

create policy team_members_select_own
on public.team_members
for select
to authenticated
using (user_id = auth.uid());

create policy documents_select_team_members
on public.documents
for select
to authenticated
using (
  public.is_team_member(team_id)
  and deleted_at is null
);

create policy documents_insert_team_editors
on public.documents
for insert
to authenticated
with check (
  created_by = auth.uid()
  and public.is_team_editor(team_id)
);

create policy documents_update_team_editors
on public.documents
for update
to authenticated
using (
  public.is_team_editor(team_id)
)
with check (
  public.is_team_editor(team_id)
);

create policy documents_delete_creator
on public.documents
for delete
to authenticated
using (created_by = auth.uid());

revoke all on public.teams from anon, authenticated;
revoke all on public.team_members from anon, authenticated;
revoke all on public.documents from anon, authenticated;

grant select on public.teams to authenticated;
grant select on public.team_members to authenticated;
grant select on public.documents to authenticated;
grant insert, update, delete on public.documents to authenticated;

grant all on public.teams to service_role;
grant all on public.team_members to service_role;
grant all on public.documents to service_role;

revoke execute on function public.is_team_member(bigint) from public;
revoke execute on function public.is_team_editor(bigint) from public;
revoke execute on function public.can_read_document(bigint) from public;
revoke execute on function public.can_edit_document(bigint) from public;
revoke execute on function public.enforce_team_immutability() from public;
revoke execute on function public.enforce_team_membership_immutability() from public;
revoke execute on function public.enforce_document_constraints() from public;

grant execute on function public.is_team_member(bigint) to anon, authenticated, service_role;
grant execute on function public.is_team_editor(bigint) to anon, authenticated, service_role;
grant execute on function public.can_read_document(bigint) to anon, authenticated, service_role;
grant execute on function public.can_edit_document(bigint) to anon, authenticated, service_role;
