create function public.enforce_team_immutability()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return old;
  end if;

  if tg_op = 'INSERT' then
    raise exception 'teams cannot be inserted by users';
  elsif tg_op = 'UPDATE' then
    if new.id is distinct from old.id
       or new.name is distinct from old.name then
      raise exception 'teams cannot be modified by users';
    end if;
  elsif tg_op = 'DELETE' then
    raise exception 'teams cannot be deleted by users';
  end if;

  return old;
end;
$$;

create function public.enforce_membership_immutability()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return old;
  end if;

  if tg_op = 'INSERT' then
    raise exception 'team memberships cannot be inserted by users';
  elsif tg_op = 'UPDATE' then
    if new.team_id is distinct from old.team_id
       or new.user_id is distinct from old.user_id
       or new.role is distinct from old.role then
      raise exception 'team memberships cannot be modified by users';
    end if;
  elsif tg_op = 'DELETE' then
    raise exception 'team memberships cannot be deleted by users';
  end if;

  return old;
end;
$$;

create function public.enforce_document_rules()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return old;
  end if;

  if tg_op = 'INSERT' then
    if new.created_by is distinct from auth.uid() then
      raise exception 'documents must be created by the current user';
    end if;

    if not public.is_team_editor(new.team_id) then
      raise exception 'only team editors can create documents in this team';
    end if;

    if new.deleted_at is not null then
      raise exception 'new documents cannot be marked as deleted';
    end if;
  elsif tg_op = 'UPDATE' then
    if new.team_id is distinct from old.team_id then
      raise exception 'document team cannot be changed';
    end if;

    if new.created_by is distinct from old.created_by then
      raise exception 'document creator cannot be changed';
    end if;

    if public.is_team_editor(old.team_id) then
      if not public.is_team_editor(new.team_id) then
        raise exception 'editors can only edit documents in teams where they are editors';
      end if;
    else
      if new.deleted_at is not null and old.deleted_at is null then
        if auth.uid() = old.created_by then
          return new;
        else
          raise exception 'only the document creator can delete it';
        end if;
      elsif new.deleted_at is null and old.deleted_at is not null then
        if auth.uid() = old.created_by then
          return new;
        else
          raise exception 'only the document creator can delete it';
        end if;
      end if;
    end if;
  end if;

  return new;
end;
$$;

