for delete
to authenticated
using (created_by = auth.uid() and status = 'draft');

create function public.invoices_enforce_immutability()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.created_by is distinct from auth.uid() then
      raise exception 'invoices.created_by cannot be set to another user';
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if new.created_by is distinct from old.created_by then
      raise exception 'invoices.created_by cannot be changed';
    end if;

    if old.created_by = auth.uid() and old.status = 'draft' then
      if new.status not in ('draft', 'sent') then
        raise exception 'draft invoices can only remain draft or become sent';
      end if;
      return new;
    end if;

    if public.is_finance_staff() and old.status = 'sent' then
      if new.status not in ('paid', 'void') then
        raise exception 'finance staff can only mark sent invoices as paid or void';
      end if;
      if new.customer is distinct from old.customer
         or new.amount is distinct from old.amount then
        raise exception 'customer and amount cannot be changed on sent invoices';
      end if;
      return new;
    end if;

    raise exception 'invoice % cannot be modified', old.id;
  end if;

  return new;
end;
$$;

create trigger invoices_enforce_immutability
before insert or update on public.invoices
for each row
execute function public.invoices_enforce_immutability();

revoke all on table public.invoices from public, anon;
grant select, insert, update, delete on table public.invoices to authenticated;
grant all on table public.invoices to service_role;
