create function public.enforce_reservation_insert()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.user_id is distinct from auth.uid() then
    raise exception 'reservations can only be created by the booking user';
  end if;

  if new.reserved_for <= now() then
    raise exception 'reservation time must be in the future';
  end if;

  if new.status <> 'booked' then
    raise exception 'new reservations must have status booked';
  end if;

  return new;
end;
$$;

create function public.enforce_reservation_update()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if old.user_id = auth.uid() then
    if new.restaurant_id <> old.restaurant_id then
      raise exception 'cannot change reservation restaurant';
    end if;

    if old.status <> 'booked' then
      raise exception 'only booked reservations can be modified';
    end if;

    if new.status = 'cancelled' then
      if new.reserved_for > now() then
        if new.user_id is distinct from auth.uid() then
          raise exception 'only the booking user can cancel';
        end if;
      else
        raise exception 'cannot cancel a reservation in the past';
      end if;
    else
      raise exception 'only booked reservations can be cancelled';
    end if;
  elsif public.is_restaurant_staff(old.restaurant_id) then
    if old.status <> 'booked' then
      raise exception 'only booked reservations can be modified by staff';
    end if;

    if new.reserved_for > now() then
      raise exception 'staff can only mark past reservations as seated or no_show';
    end if;

    if new.status not in ('seated', 'no_show') then
      raise exception 'staff can only mark reservations as seated or no_show';
    end if;

    if new.user_id is distinct from old.user_id then
      raise exception 'staff cannot change booking user';
    end if;

    if new.restaurant_id <> old.restaurant_id then
      raise exception 'staff cannot change reservation restaurant';
    end if;
  else
    raise exception 'not authorized to modify this reservation';
  end if;

  return new;
end;
$$;

