  );
$$;

create function public.dispense(p_prescription_id bigint)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_pharmacist_id uuid := auth.uid();
  v_refills_left integer;
  v_prescription public.prescriptions;
begin
  if v_pharmacist_id is null then
    raise exception 'not authenticated';
  end if;

  if not exists (
    select 1 from public.pharmacists
    where user_id = v_pharmacist_id
  ) then
    raise exception 'only pharmacists can dispense';
  end if;

  select *
    into v_prescription
    from public.prescriptions
   where id = p_prescription_id
   for update;

  if not found then
    raise exception 'prescription not found';
  end if;

  if v_prescription.patient_id = v_pharmacist_id then
    raise exception 'cannot dispense own prescription';
  end if;

  if v_prescription.expires_at < pg_catalog.now() then
    raise exception 'prescription has expired';
  end if;

  if v_prescription.refills_left <= 0 then
    raise exception 'no refills left';
  end if;

  v_refills_left := v_prescription.refills_left - 1;

  update public.prescriptions
     set refills_left = v_refills_left
   where id = p_prescription_id;

  insert into public.dispenses (prescription_id, pharmacist_id)
  values (p_prescription_id, v_pharmacist_id);

  return v_refills_left;
end;
$$;

