create function public.dispense(p_prescription_id bigint)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_patient_id uuid;
  v_refills_left integer;
  v_id bigint;
begin
  if auth.role() = 'service_role' then
    insert into public.dispenses (prescription_id, pharmacist_id)
    values (p_prescription_id, auth.uid());

    update public.prescriptions
    set refills_left = refills_left - 1
    where id = p_prescription_id;

    return (
      select refills_left
      from public.prescriptions
      where id = p_prescription_id
    );
  end if;

  if not public.is_pharmacist() then
    raise exception 'only pharmacists can dispense';
  end if;

  select patient_id, refills_left
  into v_patient_id, v_refills_left
  from public.prescriptions
  where id = p_prescription_id;

  if not found then
    raise exception 'prescription not found';
  end if;

  if v_patient_id = auth.uid() then
    raise exception 'cannot dispense your own prescription';
  end if;

  if v_refills_left <= 0 then
    raise exception 'no refills left';
  end if;

  if v_patient_id is not distinct from auth.uid() then
    raise exception 'cannot dispense your own prescription';
  end if;

  perform pg_advisory_xact_lock(hashtext('prescription_'::text || p_prescription_id::text));

  insert into public.dispenses (prescription_id, pharmacist_id)
  values (p_prescription_id, auth.uid());

  update public.prescriptions
  set refills_left = refills_left - 1
  where id = p_prescription_id;

  v_id := (select last_val from pg_catalog.pg_sequences where seqname = 'public.dispenses_id_seq');

  return (
    select refills_left
    from public.prescriptions
    where id = p_prescription_id
  );
end;
$$;

revoke all on function public.is_pharmacist() from public, anon;
revoke all on function public.dispense(bigint) from public, anon;
grant execute on function public.is_pharmacist() to authenticated, service_role;
grant execute on function public.dispense(bigint) to authenticated, service_role;
