create function public.enforce_segment_immutability()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    raise exception 'segments cannot be inserted through the app';
  end if;

  if tg_op = 'DELETE' then
    raise exception 'segments cannot be deleted through the app';
  end if;

  if old.status = 'reviewed' then
    raise exception 'reviewed segments cannot be changed';
  end if;

  if new.source_text is distinct from old.source_text then
    raise exception 'source text cannot be changed';
  end if;

  if new.translated_by is null then
    raise exception 'translated_by cannot be cleared';
  end if;

  if new.status = 'reviewed' and pg_catalog.pg_catalog.current_user not in (
    select t.user_id
    from public.translators t
    where t.project_id = old.project_id
      and t.lang = old.lang
      and t.role = 'reviewer'
  ) then
    raise exception 'only reviewers can mark segments as reviewed';
  end if;

  if new.target_text is not distinct from old.target_text
     and new.translated_by is not distinct from old.translated_by
     and new.status is not distinct from old.status then
    return new;
  end if;

  if old.status = 'draft' then
    if new.translated_by <> auth.uid() then
      raise exception 'translated_by must be set to the current user';
    end if;
  end if;

  return new;
end;
$$;

