create function public.sign_envelope(p_envelope_id bigint) returns text
language plpgsql security definer set search_path = ''
as $$
declare
  v_envelope public.envelopes%rowtype;
  v_user uuid := auth.uid();
  v_signed_count integer;
  v_total integer;
begin
  if v_user is null then
    raise exception 'not authenticated';
  end if;

  select * into v_envelope
  from public.envelopes
  where id = p_envelope_id
  for update;

  if not found then
    raise exception 'envelope not found';
  end if;

  if not exists (
    select 1 from public.envelope_recipients
    where envelope_id = p_envelope_id and user_id = v_user
  ) then
    raise exception 'not a recipient of this envelope';
  end if;

  if v_envelope.status <> 'sent' then
    raise exception 'envelope is not sent';
  end if;

  if exists (
    select 1 from public.envelope_recipients
    where envelope_id = p_envelope_id and user_id = v_user and signed_at is not null
  ) then
    raise exception 'already signed';
  end if;

  select count(*) into v_total
  from public.envelope_recipients
  where envelope_id = p_envelope_id;

  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id and user_id = v_user and signed_at is null;

  select count(*) into v_signed_count
  from public.envelope_recipients
  where envelope_id = p_envelope_id and signed_at is not null;

  if v_signed_count < v_total then
    if exists (
      select 1 from public.envelope_recipients
      where envelope_id = p_envelope_id
        and sign_order < (select sign_order from public.envelope_recipients where envelope_id = p_envelope_id and user_id = v_user)
