create function public.is_org_admin(target_org_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.org_admins
    where org_id = target_org_id
      and user_id = auth.uid()
  );
$$;

create function public.can_access_device(target_device_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.devices
    where id = target_device_id
      and (assigned_to = auth.uid() or public.is_org_admin(org_id))
  );
$$;

create function public.enforce_device_command_immutability()
returns trigger
language plpgsql
as $$
begin
  if tg_op = 'INSERT' then
    if new.issued_by is distinct from auth.uid() then
      raise exception 'device commands can only be issued by the current user';
    end if;
    if new.command not in ('locate', 'lock', 'wipe') then
      raise exception 'invalid device command';
    end if;
  else
    raise exception 'device commands are immutable';
  end if;
  return new;
end;
$$;

create policy "devices_select_assigned_or_admin"
on public.devices
for select
to authenticated
using (assigned_to = auth.uid() or public.is_org_admin(org_id));

create policy "device_commands_select_assigned_or_admin"
on public.device_commands
for select
to authenticated
using (public.can_access_device(device_id));

create policy "device_commands_insert_authorized"
on public.device_commands
for insert
to authenticated
with check (
  issued_by = auth.uid()
  and public.is_org_admin(public.devices.org_id)
  and command in ('locate', 'lock', 'wipe')
)
or (
  issued_by = auth.uid()
  and command in ('locate', 'lock')
  and public.can_access_device(device_id)
);

create trigger device_commands_enforce_immutability
before insert or update on public.device_commands
for each row
execute function public.enforce_device_command_immutability();

revoke all on table public.org_admins from public, anon, authenticated;
revoke all on table public.devices from public, anon, authenticated;
revoke all on table public.device_commands from public, anon, authenticated;

grant select on table public.devices to authenticated;
grant select on table public.device_commands to authenticated;
grant insert (device_id, command, issued_by) on table public.device_commands to authenticated;

grant all on table public.org_admins to service_role;
grant all on table public.devices to service_role;
grant all on table public.device_commands to service_role;

revoke all on sequence public.device_commands_id_seq from public, anon, authenticated;
grant usage, select on sequence public.device_commands_id_seq to authenticated, service_role;
