create function public.enforce_permits_immutable()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.revoked or (new.valid_until - current_date) > interval '365 days' then
      raise exception 'permits must be active and valid for at most 365 days';
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if old.revoked and new.revoked = false then
      raise exception 'permits cannot be un-revoked';
    end if;

    if public.is_hoa_admin() then
      if new.revoked then
        return new;
      else
        raise exception 'only HOA admins can revoke permits';
      end if;
    else
      if new.unit_id <> old.unit_id
         or new.valid_until <> old.valid_until
         or new.revoked <> old.revoked then
        raise exception 'only plate can be changed';
      end if;
      return new;
    end if;
  end if;

  return new;
end;
$$;

